"use client"

import { useEffect, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { ChefHat, CheckCircle2, Utensils } from "lucide-react"
import { useKitchenStore, KitchenStoreProvider } from "@/lib/store/kitchen-store"
import { KitchenOrderCard } from "./kitchen-order-card"

function KitchenDashboardContent() {
  const { state, updateStatus } = useKitchenStore()
  
  // Las estadísticas ahora se calculan directamente del estado real
  const stats = {
    pending: state.orderQueue.length,
    completed: state.completedOrders.length,
  }

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header - Sin botón de Demo */}
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-3xl font-bold text-foreground flex items-center gap-2">
              <ChefHat className="h-8 w-8 text-primary" />
              Panel de Cocina
            </h1>
            <p className="text-muted-foreground">Gestiona los pedidos entrantes en tiempo real</p>
          </div>
          
          <div className="flex gap-4">
            <div className="bg-card border border-border px-4 py-2 rounded-lg shadow-sm">
              <p className="text-xs text-muted-foreground uppercase font-semibold">Pendientes</p>
              <p className="text-2xl font-bold text-primary">{stats.pending}</p>
            </div>
            <div className="bg-card border border-border px-4 py-2 rounded-lg shadow-sm">
              <p className="text-xs text-muted-foreground uppercase font-semibold">Listos</p>
              <p className="text-2xl font-bold text-green-500">{stats.completed}</p>
            </div>
          </div>
        </header>

        {/* Main Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <AnimatePresence mode="popLayout">
            {state.orderQueue.map((order) => (
              <KitchenOrderCard 
                key={order.id} 
                order={order} 
                onMarkReady={(id) => updateStatus(id, "ready")} 
              />
            ))}
          </AnimatePresence>

          {state.orderQueue.length === 0 && (
            <div className="col-span-full py-20 text-center bg-card/50 border border-dashed border-border rounded-xl">
              <Utensils className="h-12 w-12 text-muted-foreground mx-auto mb-4 opacity-20" />
              <p className="text-muted-foreground">No hay pedidos pendientes en este momento</p>
            </div>
          )}
        </div>

        {/* Historial Reciente */}
        {state.completedOrders.length > 0 && (
          <div className="mt-12">
            <h2 className="font-semibold text-lg mb-4 flex items-center gap-2">
              <CheckCircle2 className="h-5 w-5 text-green-500" />
              Completados Recientemente
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
              {state.completedOrders.slice(0, 4).map((order) => (
                <div key={order.id} className="p-3 bg-card border border-border rounded-lg flex justify-between items-center text-sm">
                  <span className="font-mono font-medium">#{order.id.slice(-6)}</span>
                  <span className="text-muted-foreground">{order.customerName}</span>
                  <span className="text-green-500 font-medium">Listo</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export function KitchenDashboard() {
  return (
    <KitchenStoreProvider>
      <KitchenDashboardContent />
    </KitchenStoreProvider>
  )
}